import type { AppConfig } from "awatif/templates";

// Cornerstone Pressure Washing: a 70'-0" clear-span steel building section in
// the XZ work plane. W16x67 columns on grids A and B carry a parallel-chord
// 4:12 HSS Warren truss with an 8" overhang at A and a 5'-0" overhang at B.
// Dimensions are taken from the section drawing and converted to metres, with
// z = 0 at top of footing (2'-0" above floor).

const ft = 0.3048;
const span = 70 * ft; // grid A to grid B
const half = span / 2;
const slope = 4 / 12;
const columnHeight = (19 + 6.75 / 12) * ft; // T.O.F. to top of column
const trussUnderside = (16 + 8 / 12) * ft; // T.O.F. to U/S of truss
const overhangA = (8 / 12) * ft;
const overhangB = 5 * ft;
const panels = 8; // web panels per half span (~4'-7" along the slope)
const panel = half / panels;

const rise = (x: number) => slope * (half - Math.abs(x - half));
const topZ = (x: number) => columnHeight + rise(x);
const bottomZ = (x: number) => trussUnderside + rise(x);

const points: [number, number, number][] = [];
const addPoint = (x: number, z: number) => points.push([x, 0, z]);

const lines: [number, number][] = [];
const addLine = (i: number, j: number) => lines.push([i, j]);

// Column bases
const baseA = addPoint(0, 0);
const baseB = addPoint(span, 0);

// Top chord nodes at every panel point, plus the overhang tips
const top: number[] = [];
for (let i = 0; i <= 2 * panels; i++) top.push(addPoint(i * panel, topZ(i * panel)));
const tipA = addPoint(-overhangA, columnHeight - slope * overhangA);
const tipB = addPoint(span + overhangB, columnHeight - slope * overhangB);

// Bottom chord nodes: at the columns, the ridge and each panel midpoint
const bottomA = addPoint(0, trussUnderside);
const bottomB = addPoint(span, trussUnderside);
const bottomRidge = addPoint(half, bottomZ(half));
const mid: number[] = [];
for (let i = 0; i < 2 * panels; i++) {
  const x = (i + 0.5) * panel;
  mid.push(addPoint(x, bottomZ(x)));
}

// Columns run through the bottom chord connection to the top chord
const columns = [
  addLine(baseA, bottomA),
  addLine(bottomA, top[0]),
  addLine(baseB, bottomB),
  addLine(bottomB, top[2 * panels]),
];

const topChord = [addLine(tipA, top[0]), addLine(top[2 * panels], tipB)];
for (let i = 0; i < 2 * panels; i++) topChord.push(addLine(top[i], top[i + 1]));

const bottomNodes = [
  bottomA,
  ...mid.slice(0, panels),
  bottomRidge,
  ...mid.slice(panels),
  bottomB,
];
const bottomChord: number[] = [];
for (let i = 0; i < bottomNodes.length - 1; i++)
  bottomChord.push(addLine(bottomNodes[i], bottomNodes[i + 1]));

// Warren diagonals in each panel and a vertical at the ridge
const webs = [addLine(top[panels], bottomRidge)];
for (let i = 0; i < 2 * panels; i++) {
  webs.push(addLine(top[i], mid[i]));
  webs.push(addLine(mid[i], top[i + 1]));
}

