import type { AppConfig } from "awatif/templates";

// CIV312 4-storey steel building (resources/civ312_project_*.png).
// Plan: grid 1-5 along X at 7.0 m, grid D-A along Y at 7.0 m (A = north).
// Storeys 1-2 cover the full 4 x 3 bay plan; storey 3 and the roof cover
// lines 2-4 only. Storey height 3.7 m.
// Lateral system: MRF in N-S on lines 2 and 4, chevron CBF in E-W on lines
// A and D between lines 2 and 4 (apex at line 3). Line 3 is a gravity frame.

const bay = 7.0;
const storey = 3.7;

const xs = [0, 1, 2, 3, 4].map((i) => i * bay); // grid 1..5
const ys = [0, 1, 2, 3].map((j) => j * bay); // grid D, C, B, A
const zs = [0, 1, 2, 3, 4].map((k) => k * storey); // base .. roof

// Plan grid indices (into xs) present at a given level index
const xRange = (k: number) => (k <= 2 ? [0, 1, 2, 3, 4] : [1, 2, 3]);

const points: [number, number, number][] = [];
const pointIds = new Map<string, number>();
const pt = (i: number, j: number, k: number) => {
  const key = `${i},${j},${k}`;
  if (!pointIds.has(key)) {
    points.push([xs[i], ys[j], zs[k]]);
    pointIds.set(key, points.length);
  }
  return pointIds.get(key)!;
};

const lines: [number, number][] = [];
const addLine = (a: number, b: number) => {
  lines.push([a, b]);
  return lines.length;
};

const bases: number[] = [];
const mrfColumns: number[] = [];
const mrfBeams: number[] = [];
const cbfColumns: number[] = [];
const cbfBeams: number[] = [];
const braces: number[] = [];
const gravityColumns: number[] = [];
const gravityBeams: number[] = [];

const isMrfLine = (i: number) => i === 1 || i === 3; // lines 2 and 4
const isCbfBay = (i: number, j: number) =>
  (j === 0 || j === 3) && i >= 1 && i < 3; // lines D and A, bays 2-3 and 3-4

// Columns
for (let k = 1; k <= 4; k++) {
  for (const i of xRange(k)) {
    for (let j = 0; j < 4; j++) {
      if (k === 1) bases.push(pt(i, j, 0));
      const id = addLine(pt(i, j, k - 1), pt(i, j, k));
      if (isMrfLine(i)) mrfColumns.push(id);
      else if ((j === 0 || j === 3) && i === 2) cbfColumns.push(id);
      else gravityColumns.push(id);
    }
  }
}

// Floor and roof beams
for (let k = 1; k <= 4; k++) {
  const range = xRange(k);
  // E-W beams (along X)
  for (let j = 0; j < 4; j++) {
    for (const i of range.slice(0, -1)) {
      const id = addLine(pt(i, j, k), pt(i + 1, j, k));
      (isCbfBay(i, j) ? cbfBeams : gravityBeams).push(id);
    }
  }
  // N-S beams (along Y)
  for (const i of range) {
    for (let j = 0; j < 3; j++) {
      const id = addLine(pt(i, j, k), pt(i, j + 1, k));
      (isMrfLine(i) ? mrfBeams : gravityBeams).push(id);
    }
  }
}

// Chevron braces on lines D and A: from lines 2 and 4 at the lower level up to
// line 3 at the upper level
for (const j of [0, 3]) {
  for (let k = 1; k <= 4; k++) {
    braces.push(addLine(pt(1, j, k - 1), pt(2, j, k)));
    braces.push(addLine(pt(3, j, k - 1), pt(2, j, k)));
  }
}

const allLines = lines.map((_, idx) => idx + 1);

export const civ312Building: AppConfig = {
